int main(void){pl_ptt s={.armed=true};assert(!pl_ptt_request(&s,0));pl_ptt_hold(&s,true);uint32_t request=pl_ptt_request(&s,0);assert(request);assert(!pl_ptt_request(&s,1));pl_ptt_hold(&s,false);assert(!pl_ptt_grant(&s,request,1,2));pl_ptt_hold(&s,true);uint32_t next=pl_ptt_request(&s,3);assert(next!=request);assert(!pl_ptt_grant(&s,request,1,4));assert(pl_ptt_deny(&s,next));assert(!pl_ptt_request(&s,5));pl_ptt_hold(&s,false);pl_ptt_hold(&s,true);next=pl_ptt_request(&s,6);assert(pl_ptt_grant(&s,next,2,7));assert(!pl_ptt_expire(&s,29000006));assert(pl_ptt_expire(&s,29000007)==2);assert(!pl_ptt_request(&s,29000008));pl_ptt_hold(&s,false);pl_ptt_hold(&s,true);next=pl_ptt_request(&s,30000000);assert(pl_ptt_timeout(&s,33000000));assert(!pl_ptt_grant(&s,next,3,33000001));pl_ptt_hold(&s,false);pl_ptt_hold(&s,true);next=pl_ptt_request(&s,34000000);assert(pl_ptt_grant(&s,next,4,34000001));assert(pl_ptt_floor(&s,0));assert(!s.stream);puts("PTT early release, stale grant, contention, request timeout and lease: PASS");}
